import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.boot.context.properties.bind.DefaultValue;
import org.springframework.validation.annotation.Validated;
import jakarta.validation.constraints.*;
import java.time.Duration;
import java.util.List;
import java.util.Map;

// 1. 类型安全配置类：松散绑定 + JSR-303 校验 + Duration/Map/List
@ConfigurationProperties(prefix = "app.datasource")
@Validated
public class DataSourceProperties {
    @NotBlank
    private String url;
    @NotBlank
    private String username;
    @NotBlank
    private String password;
    @Min(1)
    @Max(100)
    @DefaultValue("10")
    private int maxPoolSize;
    private Duration connectionTimeout = Duration.ofSeconds(30);
    private Map<String, String> customProperties;
    private List<String> preferredDialects;

    // getter/setter 省略
}

// 2. Profile 切换 Bean
import org.springframework.context.annotation.*;
import javax.sql.DataSource;

@Configuration
public class DataSourceConfig {
    @Bean
    @Profile("dev")
    public DataSource devDataSource(DataSourceProperties props) {
        // 开发环境：本地 H2 或 dev MySQL
        return createDataSource(props.getUrl(), props.getUsername(), props.getPassword());
    }

    @Bean
    @Profile("prod")
    public DataSource prodDataSource(DataSourceProperties props) {
        // 生产环境：读写分离、连接池参数保守
        return createDataSource(props.getUrl(), props.getUsername(), props.getPassword());
    }

    private DataSource createDataSource(String url, String user, String pass) {
        com.zaxxer.hikari.HikariConfig config = new com.zaxxer.hikari.HikariConfig();
        config.setJdbcUrl(url);
        config.setUsername(user);
        config.setPassword(pass);
        return new com.zaxxer.hikari.HikariDataSource(config);
    }
}

// 3. application.yml 示例
// app:
//   datasource:
//     url: jdbc:mysql://localhost:3306/dev_db
//     username: dev
